// UserServiceServer is the server API for UserService service.
// All implementations must embed UnimplementedUserServiceServer
// for forward compatibility.
//
// The user service definition.
type UserServiceServer interface {
	// Login authenticates a user and returns JWT tokens.
	Login(context.Context, *LoginRequest) (*LoginResponse, error)
	// Logout invalidates the current session.
	Logout(context.Context, *LogoutRequest) (*LogoutResponse, error)
	// RefreshToken refreshes the access token using a refresh token.
	RefreshToken(context.Context, *RefreshTokenRequest) (*RefreshTokenResponse, error)
	// Register creates a new user account.
	Register(context.Context, *RegisterRequest) (*RegisterResponse, error)
	// GetCurrentUser returns the current authenticated user.
	GetCurrentUser(context.Context, *GetCurrentUserRequest) (*GetCurrentUserResponse, error)
	// GetMe returns the current user's information.
	GetMe(context.Context, *GetMeRequest) (*GetMeResponse, error)
	// UpdateMe updates the current user's information.
	UpdateMe(context.Context, *UpdateMeRequest) (*UpdateMeResponse, error)
	// UpdateMyPassword updates the current user's password.
	UpdateMyPassword(context.Context, *UpdateMyPasswordRequest) (*UpdateMyPasswordResponse, error)
	// GetMyPlaylists returns the current user's playlists.
	GetMyPlaylists(context.Context, *GetMyPlaylistsRequest) (*GetMyPlaylistsResponse, error)
	// GetMyFavorites returns the current user's favorites.
	GetMyFavorites(context.Context, *GetMyFavoritesRequest) (*GetMyFavoritesResponse, error)
	// GetMyLikes returns the current user's likes.
	GetMyLikes(context.Context, *GetMyLikesRequest) (*GetMyLikesResponse, error)
	// GetMySubscriptions returns the current user's channel subscriptions.
	GetMySubscriptions(context.Context, *GetMySubscriptionsRequest) (*GetMySubscriptionsResponse, error)
	// GetMyHistory returns the current user's watch history.
	GetMyHistory(context.Context, *GetMyHistoryRequest) (*GetMyHistoryResponse, error)
	// UpsertHistory creates or updates a history record (progress reporting).
	UpsertHistory(context.Context, *UpsertHistoryRequest) (*UpsertHistoryResponse, error)
	// SyncHistory batch-syncs history records (login merge).
	SyncHistory(context.Context, *SyncHistoryRequest) (*SyncHistoryResponse, error)
	// ClearHistory clears all watch history for the current user.
	ClearHistory(context.Context, *ClearHistoryRequest) (*ClearHistoryResponse, error)
	// RemoveHistoryItem removes a single history record.
	RemoveHistoryItem(context.Context, *RemoveHistoryItemRequest) (*RemoveHistoryItemResponse, error)
	// GetMyStats returns the current user's statistics.
	GetMyStats(context.Context, *GetMyStatsRequest) (*GetMyStatsResponse, error)
	// ListUsers returns a list of users.
	ListUsers(context.Context, *ListUsersRequest) (*ListUsersResponse, error)
	// GetUser returns a user by slug (portal) or ID (admin).
	GetUser(context.Context, *GetUserRequest) (*GetUserResponse, error)
	// CreateUser creates a new user.
	CreateUser(context.Context, *CreateUserRequest) (*CreateUserResponse, error)
	// UpdateUser updates an existing user.
	UpdateUser(context.Context, *UpdateUserRequest) (*UpdateUserResponse, error)
	// DeleteUser deletes a user.
	DeleteUser(context.Context, *DeleteUserRequest) (*DeleteUserResponse, error)
	// UpdateUserStatus updates a user's status.
	UpdateUserStatus(context.Context, *UpdateUserStatusRequest) (*UpdateUserStatusResponse, error)
	// UpdateUserRoles updates a user's roles.
	UpdateUserRoles(context.Context, *UpdateUserRolesRequest) (*UpdateUserRolesResponse, error)
	// ChangeUserPassword changes a user's password.
	ChangeUserPassword(context.Context, *ChangeUserPasswordRequest) (*ChangeUserPasswordResponse, error)
	// VerifyPassword verifies if the provided password matches the user's password.
	VerifyPassword(context.Context, *VerifyPasswordRequest) (*VerifyPasswordResponse, error)
	// ListUserRoles returns roles assigned to a user.
	ListUserRoles(context.Context, *ListUserRolesRequest) (*ListUserRolesResponse, error)
	// GetUserStats returns statistics for a user.
	GetUserStats(context.Context, *GetUserStatsRequest) (*GetUserStatsResponse, error)
	// GetUserPlaylists returns public playlists for a user.
	GetUserPlaylists(context.Context, *GetUserPlaylistsRequest) (*GetUserPlaylistsResponse, error)
	// GetUserFollowers returns followers for a user.
	GetUserFollowers(context.Context, *GetUserFollowersRequest) (*GetUserFollowersResponse, error)
	// GetUserByUsername returns a user by username.
	GetUserByUsername(context.Context, *GetUserByUsernameRequest) (*GetUserByUsernameResponse, error)
	// SubscribeUser subscribes to a user.
	SubscribeUser(context.Context, *SubscribeUserRequest) (*SubscribeUserResponse, error)
	// UnsubscribeUser unsubscribes from a user.
	UnsubscribeUser(context.Context, *UnsubscribeUserRequest) (*UnsubscribeUserResponse, error)
	// GetUserSubscription returns subscription status for a user.
	GetUserSubscription(context.Context, *GetUserSubscriptionRequest) (*GetUserSubscriptionResponse, error)
	// GetMyFollowers returns the current user's followers.
	GetMyFollowers(context.Context, *GetMyFollowersRequest) (*GetMyFollowersResponse, error)
	// GetMyChannels returns the current user's channels.
	GetMyChannels(context.Context, *GetMyChannelsRequest) (*GetMyChannelsResponse, error)
	// RemoveFavorite removes a favorite for the current user.
	RemoveFavorite(context.Context, *RemoveFavoriteRequest) (*RemoveFavoriteResponse, error)
	// UpdateMySlug updates the current user's slug.
	UpdateMySlug(context.Context, *UpdateMySlugRequest) (*UpdateMySlugResponse, error)
	// GetUserLikes returns likes for a user.
	GetUserLikes(context.Context, *GetUserLikesRequest) (*GetUserLikesResponse, error)
	// GetUserSubscriptions returns subscriptions for a user.
	GetUserSubscriptions(context.Context, *GetUserSubscriptionsRequest) (*GetUserSubscriptionsResponse, error)
	// ChangePassword changes the current user's password (auth endpoint).
	ChangePassword(context.Context, *ChangePasswordRequest) (*ChangePasswordResponse, error)
	mustEmbedUnimplementedUserServiceServer()
}

